**`event.go` — NIP-01 `NostrEvent` + Ed25519 sign/verify over the canonical serialization:**

```go
// NostrEvent is a NIP-01 event. Field order matches the NIP-01 JSON schema.
type NostrEvent struct {
	ID        string     `json:"id"`
	PubKey    string     `json:"pubkey"`
	CreatedAt int64      `json:"created_at"`
	Kind      int        `json:"kind"`
	Tags      [][]string `json:"tags"`
	Content   string     `json:"content"`
	Sig       string     `json:"sig"`
}

// Canonical serializes exactly per NIP-01:
//   [0,"<pubkey>",<created_at>,<kind>,<tags>,"<content>"]
func (e *NostrEvent) Canonical() []byte { /* bytes.Buffer; nil tags -> [] not null */ }

func (e *NostrEvent) ComputeID() string { // sha256(Canonical), lowercase hex
	sum := sha256.Sum256(e.Canonical())
	return hex.EncodeToString(sum[:])
}

// Sign computes ID and Ed25519-signs the canonical serialization (RFC 8032,
// deterministic). Derives PubKey from the private key if empty.
func (e *NostrEvent) Sign(priv ed25519.PrivateKey) error {
	if len(priv) != ed25519.PrivateKeySize { return fmt.Errorf(...) }
	pub := priv.Public().(ed25519.PublicKey)
	if e.PubKey == "" { e.PubKey = hex.EncodeToString(pub) }
	e.ID = e.ComputeID()
	e.Sig = hex.EncodeToString(ed25519.Sign(priv, e.Canonical()))
	return nil
}

// Verify returns false for malformed keys/sigs — safe with untrusted input.
func (e *NostrEvent) Verify(pub ed25519.PublicKey) bool { ... }
```

